// Minimum combined-port regression: original vs opt-in LA_VALUE, including latched near path/full44-bit tags.
`timescale 1ns/1ps
// Random cycle-for-cycle equivalence of ot_qwen_tp_seq_w12_vp LA = 1 (timing look-ahead) against
// LA = 0 (the measured adopted sequencer), both ENABLE_ARP = 1, ENABLE_AR256 = 1, QWEN_FULLSHAPE = 1.
// One stimulus (descriptor table, core, vector memory, collective) is generated by a synchronous
// environment FSM from the LA = 0 instance's handshakes and applied to both; every output of both is
// compared on every cycle (c_last / c_data only while c_valid, vm_raddr only while vm_re: the ports
// are qualified by them).  Steps mix wide
// all-reduces (count bits [23:20]), AR256, short and one-word all-reduces, ARGMAX_NEXT records (up to
// and past the 8 record slots), ARGMAX and END, with random core latency, c_ready back-pressure and
// r_valid gaps, equal and signed logits, and (last tenth of the steps: faults are sticky) injected
// r_last / r_rank / r_err / core_fault faults.
//   run: Verilator --binary --top-module tb_seq_vp_la_equiv tb_seq_vp_la_equiv.sv rtl/rom/ot_qwen_tp_seq_w12_vp.sv
`ifndef LA_VALUE
`define LA_VALUE 1
`endif
module tb_combined_seq_la_equiv;
    localparam integer N = 4, NW = 18, PAW = 12, VWA = 16, DAW = 6, FW = 512, TAGW = 44, NTOK = 8;
    localparam integer STEPS = 120;
    reg clk = 0, rst_n = 0;
    reg start; reg [NW-1:0] token, pos;
    reg near_decoder=0, nhb_done=0, nhb_fault=0;
    wire nhb_request[2];wire [23:0] nhb_qbase[2],nhb_obase[2];
    reg core_done; reg [NW-1:0] core_next_token; reg [31:0] core_next_val; reg core_fault;
    reg [FW-1:0] vm_rq_0, vm_rq_1;
    reg c_ready; reg r_valid; reg [FW-1:0] r_data; reg r_last; reg [1:0] r_rank; reg r_err;
    reg [63:0] desc [0:63];
    reg [63:0] desc_q_0, desc_q_1;
    wire done[2]; wire [NW-1:0] next_token[2]; wire [31:0] next_val[2]; wire fault[2]; wire coll_busy[2];
    wire [NTOK*NW-1:0] tok_vec[2]; wire [NTOK*32-1:0] val_vec[2]; wire [3:0] n_tok[2];
    wire core_start[2]; wire [NW-1:0] core_token[2], core_pos[2]; wire [PAW-1:0] prog_base[2];
    wire desc_re[2]; wire [DAW-1:0] desc_addr[2]; wire vm_re[2]; wire [VWA-1:0] vm_raddr[2];
    wire vm_we[2]; wire [VWA-1:0] vm_waddr[2]; wire [FW-1:0] vm_wdata[2];
    wire c_valid[2]; wire [FW-1:0] c_data[2]; wire c_last[2]; wire c_mode[2]; wire [TAGW-1:0] c_tag[2];
    genvar g;
    generate for (g = 0; g < 2; g = g + 1) begin : d
        if(g==0)begin : orig
        ot_qwen_tp_seq_combined_vp #(.NEAR_HBM(1),.ENABLE_AR256(1), .ENABLE_ARP(1), .NTOK(NTOK), .N(N), .NW(NW), .PAW(PAW),
                                .VWA(VWA), .DAW(DAW), .FW(FW), .TAGW(TAGW), .QWEN_FULLSHAPE(1)) u (
            .clk(clk), .rst_n(rst_n), .start(start), .token(token), .pos(pos), .done(done[g]),
            .next_token(next_token[g]), .next_val(next_val[g]), .fault(fault[g]), .coll_busy(coll_busy[g]),
            .tok_vec(tok_vec[g]), .val_vec(val_vec[g]), .n_tok(n_tok[g]),
            .core_start(core_start[g]), .core_token(core_token[g]), .core_pos(core_pos[g]), .core_done(core_done),
            .core_next_token(core_next_token), .core_next_val(core_next_val), .core_fault(core_fault),
            .prog_base(prog_base[g]), .desc_re(desc_re[g]), .desc_addr(desc_addr[g]),
            .desc_q(g == 0 ? desc_q_0 : desc_q_1),
            .vm_re(vm_re[g]), .vm_raddr(vm_raddr[g]), .vm_rq(g == 0 ? vm_rq_0 : vm_rq_1), .vm_we(vm_we[g]),
            .vm_waddr(vm_waddr[g]), .vm_wdata(vm_wdata[g]), .c_valid(c_valid[g]), .c_ready(c_ready),
            .c_data(c_data[g]), .c_last(c_last[g]), .c_mode(c_mode[g]), .c_tag(c_tag[g]),
            .near_decoder(near_decoder), .nhb_request(nhb_request[g]),
            .nhb_qbase(nhb_qbase[g]), .nhb_obase(nhb_obase[g]), .nhb_done(nhb_done), .nhb_fault(nhb_fault),
            .r_valid(r_valid), .r_data(r_data), .r_last(r_last), .r_rank(r_rank), .r_err(r_err));
        end else begin : newer
        ot_qwen_tp_seq_combined_vp_la #(.LA(`LA_VALUE), .NEAR_HBM(1),.ENABLE_AR256(1), .ENABLE_ARP(1), .NTOK(NTOK), .N(N), .NW(NW), .PAW(PAW),
                                .VWA(VWA), .DAW(DAW), .FW(FW), .TAGW(TAGW), .QWEN_FULLSHAPE(1)) u (
            .clk(clk), .rst_n(rst_n), .start(start), .token(token), .pos(pos), .done(done[g]),
            .next_token(next_token[g]), .next_val(next_val[g]), .fault(fault[g]), .coll_busy(coll_busy[g]),
            .tok_vec(tok_vec[g]), .val_vec(val_vec[g]), .n_tok(n_tok[g]),
            .core_start(core_start[g]), .core_token(core_token[g]), .core_pos(core_pos[g]), .core_done(core_done),
            .core_next_token(core_next_token), .core_next_val(core_next_val), .core_fault(core_fault),
            .prog_base(prog_base[g]), .desc_re(desc_re[g]), .desc_addr(desc_addr[g]),
            .desc_q(g == 0 ? desc_q_0 : desc_q_1),
            .vm_re(vm_re[g]), .vm_raddr(vm_raddr[g]), .vm_rq(g == 0 ? vm_rq_0 : vm_rq_1), .vm_we(vm_we[g]),
            .vm_waddr(vm_waddr[g]), .vm_wdata(vm_wdata[g]), .c_valid(c_valid[g]), .c_ready(c_ready),
            .c_data(c_data[g]), .c_last(c_last[g]), .c_mode(c_mode[g]), .c_tag(c_tag[g]),
            .near_decoder(near_decoder), .nhb_request(nhb_request[g]),
            .nhb_qbase(nhb_qbase[g]), .nhb_obase(nhb_obase[g]), .nhb_done(nhb_done), .nhb_fault(nhb_fault),
            .r_valid(r_valid), .r_data(r_data), .r_last(r_last), .r_rank(r_rank), .r_err(r_err));
        end
    end endgenerate
    always @(posedge clk) begin
        if (desc_re[0]) desc_q_0 <= desc[desc_addr[0]];
        if (desc_re[1]) desc_q_1 <= desc[desc_addr[1]];
        if (vm_re[0]) vm_rq_0 <= {16{8'h5a ^ vm_raddr[0][7:0], 8'h0, vm_raddr[0]}};
        if (vm_re[1]) vm_rq_1 <= {16{8'h5a ^ vm_raddr[1][7:0], 8'h0, vm_raddr[1]}};
    end
    // ---- comparison --------------------------------------------------------------------------
    integer mism = 0, cycles = 0, n_done = 0, n_fault_steps = 0, n_rec = 0, n_rec8 = 0, n_wide = 0, n_amax = 0;
    always @(negedge clk) if (rst_n) begin
        cycles = cycles + 1;
        if ({nhb_request[0],nhb_qbase[0],nhb_obase[0],done[0], next_token[0], next_val[0], fault[0], coll_busy[0], tok_vec[0], val_vec[0], n_tok[0],
             core_start[0], core_token[0], core_pos[0], prog_base[0], desc_re[0], desc_addr[0], vm_re[0], vm_re[0] ? vm_raddr[0] : {VWA{1'b0}},
             vm_we[0], vm_waddr[0], vm_wdata[0], c_valid[0], c_valid[0] ? c_data[0] : {FW{1'b0}}, c_valid[0] & c_last[0], c_mode[0], c_tag[0]} !==
            {nhb_request[1],nhb_qbase[1],nhb_obase[1],done[1], next_token[1], next_val[1], fault[1], coll_busy[1], tok_vec[1], val_vec[1], n_tok[1],
             core_start[1], core_token[1], core_pos[1], prog_base[1], desc_re[1], desc_addr[1], vm_re[1], vm_re[1] ? vm_raddr[1] : {VWA{1'b0}},
             vm_we[1], vm_waddr[1], vm_wdata[1], c_valid[1], c_valid[1] ? c_data[1] : {FW{1'b0}}, c_valid[1] & c_last[1], c_mode[1], c_tag[1]}) begin
            mism = mism + 1;
            if (mism < 10) $display("MISMATCH cycle %0d: st %0d/%0d done %b/%b n_tok %0d/%0d c_valid %b/%b c_last %b/%b vm_re %b/%b fault %b/%b",
                                    cycles, d[0].orig.u.st, d[1].newer.u.st, done[0], done[1], n_tok[0], n_tok[1], c_valid[0], c_valid[1],
                                    c_last[0], c_last[1], vm_re[0], vm_re[1], fault[0], fault[1]);
        end
    end
    // ---- environment FSM (synchronous; driven from instance 0) ---------------------------------
    localparam [2:0] E_PROG = 0, E_RUN = 1, E_CORE = 2, E_TX = 3, E_RX = 4, E_GAP = 5;
    reg [2:0] e;
    integer k, nseg, wait_n, cnt, i, inj; integer near_steps=0,near_responses=0;
    reg [1:0] kd;
    reg done_q;
    always @(posedge clk) done_q <= rst_n && done[0];
    always @(posedge clk) begin
        if (rst_n && cycles > STEPS * 4000) begin
            $display("STALL e=%0d st=%0d steps=%0d cycles=%0d mism=%0d", e, d[0].orig.u.st, n_done, cycles, mism); $display("FAIL"); $fatal(1, "EQUIVALENCE_TERMINAL_STALL");
        end
        if (rst_n) begin
            nhb_done<=0; nhb_fault<=0;
            start <= 1'b0; core_done <= 1'b0; core_fault <= 1'b0; r_valid <= 1'b0; r_last <= 1'b0; r_err <= 1'b0;
            c_ready <= ($urandom % 4 != 0);
            case (e)
                E_PROG: begin
                    near_decoder <= (n_done % 2 == 1);
                    if(n_done % 2 == 1)near_steps=near_steps+1;
                    nseg = 1 + ($urandom % 14);
                    for (k = 0; k < 64; k = k + 1) desc[k] = 64'd0;
                    for (k = 0; k < nseg; k = k + 1) begin
                        case ($urandom % 6)
                            0, 1, 5: kd = 2'd1; 2, 3: kd = 2'd3; default: kd = (k == nseg - 1) ? 2'd2 : 2'd3;
                        endcase
                        desc[k] = {$urandom, $urandom};
                        desc[k][1:0] = kd;
                        if (kd == 2'd1) begin
                            case ($urandom % 4)
                                0: begin desc[k][17:10] = 8'd0; desc[k][23:20] = 4'd0; end
                                1: begin desc[k][17:10] = 1 + ($urandom % 6); desc[k][23:20] = 4'd0; end
                                2: begin desc[k][17:10] = $urandom % 3; desc[k][23:20] = 1 + ($urandom % 2); n_wide = n_wide + 1; end
                                default: begin desc[k][17:10] = 1; desc[k][23:20] = 4'd0; end
                            endcase
                        end
                    end
                    if (desc[nseg-1][1:0] != 2'd2) desc[nseg][1:0] = 2'd0;
                    inj = (n_done >= STEPS * 9 / 10) && ($urandom % 4 == 0);   // faults are sticky: the last tenth only
                    token <= $urandom; pos <= $urandom;
                    start <= 1'b1; e <= E_RUN;
                end
                E_RUN: begin
                    if (done[0] && !done_q) begin
                        n_done = n_done + 1;
                        if (fault[0]) n_fault_steps = n_fault_steps + 1;
                        n_rec = n_rec + n_tok[0];
                        if (n_tok[0] == NTOK) n_rec8 = n_rec8 + 1;
                        if (n_done % 2000 == 0) $display("progress steps=%0d cycles=%0d mism=%0d", n_done, cycles, mism);
                        if (n_done == STEPS) begin
                            $display("EQUIV steps=%0d cycles=%0d wide_ar=%0d records=%0d full8_steps=%0d fault_steps=%0d mismatches=%0d",
                                     n_done, cycles, n_wide, n_rec, n_rec8, n_fault_steps, mism);
                            if (mism == 0 && near_steps>0 && near_responses>0 && n_wide>0 && n_rec>0) $display("PASS LA=%0d near_steps=%0d near_responses=%0d",`LA_VALUE,near_steps,near_responses); else $display("FAIL");
                            if (!(mism == 0 && near_steps>0 && near_responses>0 && n_wide>0 && n_rec>0)) $fatal(1, "EQUIVALENCE_TERMINAL_FAIL");
                            $finish;
                        end
                        e <= E_GAP; wait_n = $urandom % 3;
                    end else if (nhb_request[0]) begin
                        nhb_done<=($urandom % 4 == 0);
                        if($urandom % 4 == 0)near_responses=near_responses+1;
                    end else if (core_start[0]) begin
                        wait_n = $urandom % 5; e <= E_CORE;
                    end else if (coll_busy[0] && c_valid[0] && c_ready && c_last[0]) begin
                        cnt = c_mode[0] ? N : d[0].orig.u.nw; i = 0; wait_n = $urandom % 3; e <= E_RX;
                        if (c_mode[0]) n_amax = n_amax + 1;
                    end
                end
                E_CORE: if (wait_n == 0) begin
                    core_done <= 1'b1; core_next_token <= $urandom; core_next_val <= $urandom;
                    core_fault <= inj && ($urandom % 8 == 0);
                    e <= E_RUN;
                end else wait_n = wait_n - 1;
                E_RX: if (wait_n == 0) begin
                    r_valid <= 1'b1;
                    r_data <= {16{$urandom}};
                    r_data[32 +: NW] <= $urandom;
                    r_data[31:0] <= ($urandom % 3 == 0) ? 32'h8000_0000 : (($urandom % 4 == 0) ? 32'h3f80_0000 : $urandom);
                    r_last <= (i == cnt - 1); r_rank <= i[1:0]; r_err <= 1'b0;
                    if (inj && $urandom % 6 == 0)
                        case ($urandom % 3) 0: r_last <= (i != cnt - 1); 1: r_rank <= i[1:0] + 2'd1; default: r_err <= 1'b1; endcase
                    i = i + 1; wait_n = $urandom % 3;
                    if (i == cnt) e <= E_RUN;
                end else wait_n = wait_n - 1;
                E_GAP: if (wait_n == 0) e <= E_PROG; else wait_n = wait_n - 1;
                default: e <= E_PROG;
            endcase
        end
    end
    initial begin
        e = E_PROG; start = 0; token = 0; pos = 0; core_done = 0; core_next_token = 0; core_next_val = 0; core_fault = 0;
        c_ready = 0; r_valid = 0; r_data = 0; r_last = 0; r_rank = 0; r_err = 0;
        repeat (6) begin #1 clk = ~clk; end
        rst_n = 1;
        forever begin #1 clk = ~clk; end
    end
endmodule
